    VALUES (NULL, $q$Composites - Vacuum bag$q$, 'process', 'single', false, true, true, $q$Bagging the laid-up part for cure: release peel ply, release film and breather over the tool (their laying rates), unrolling the bag (vacuumBagMaterialUnrollRate), taping its sealant round the tool (applyVacuumBagRate, sealantTapeLengthMultiplier) and its vacuum port.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Bagging the laid-up part for cure: release peel ply, release film and breather over the tool (their laying rates), unrolling the bag (vacuumBagMaterialUnrollRate), taping its sealant round the tool (applyVacuumBagRate, sealantTapeLengthMultiplier) and its vacuum port.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Tool Side Area$q$, $q$Tool Side Area (mm²)$q$, $q$number$q$, $q$mm²$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Trim Length$q$, $q$Trim Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Tool Allowance$q$, $q$Tool Allowance (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Tool Area$q$, $q$Tool Area (mm²)$q$, $q$calculated$q$, $q$mm²$q$, NULL, NULL, NULL, $q${Tool Side Area} + {Trim Length} * {Tool Allowance} + 4 * {Tool Allowance} ^ 2$q$, 4, false),
    (v_id, $q$Peel Ply Rate$q$, $q$Peel Ply Rate (mm²/s)$q$, $q$number$q$, $q$mm²/s$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Release Film Rate$q$, $q$Release Film Rate (mm²/s)$q$, $q$number$q$, $q$mm²/s$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Breather Rate$q$, $q$Breather Rate (mm²/s)$q$, $q$number$q$, $q$mm²/s$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Bag Unroll Rate$q$, $q$Bag Unroll Rate (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Footprint Length$q$, $q$Footprint Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 9, true),
    (v_id, $q$Bag Tape Rate$q$, $q$Bag Tape Rate (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 10, true),
    (v_id, $q$Sealant Multiplier$q$, $q$Sealant Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 11, true),
    (v_id, $q$Vacuum Port Time$q$, $q$Vacuum Port Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 12, true),
    (v_id, $q$Bag Perimeter$q$, $q$Bag Perimeter (mm)$q$, $q$calculated$q$, $q$mm$q$, NULL, NULL, NULL, $q${Trim Length} + 8 * {Tool Allowance}$q$, 13, false),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 14, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Tool Area} / {Peel Ply Rate} + {Tool Area} / {Release Film Rate} + {Tool Area} / {Breather Rate} + ({Footprint Length} + 2 * {Tool Allowance}) / {Bag Unroll Rate} + {Bag Perimeter} * {Sealant Multiplier} / {Bag Tape Rate} + {Vacuum Port Time}) * {Cycle Time Factor}$q$, 15, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Composites - Vacuum bag$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Composites$q$ AND operation IN ($q$Vacuum Bag$q$, $q$Final Vacuum Bag$q$);
END
$calc$;

-- Composites - Autoclave cure
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Composites - Autoclave cure$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Composites - Autoclave cure$q$, 'process', 'single', false, true, true, $q$Curing in the autoclave: moving the load in (moveIntoAutoclaveTime), the resin's cure cycle (ramp up from resinCureRampUpStartTemperature at the material's rate, dwell at its hold temperature, ramp down to resinCureRampDownFinishTemperature), shared by the parts in the load (Composites - Autoclave load).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Curing in the autoclave: moving the load in (moveIntoAutoclaveTime), the resin's cure cycle (ramp up from resinCureRampUpStartTemperature at the material's rate, dwell at its hold temperature, ramp down to resinCureRampDownFinishTemperature), shared by the parts in the load (Composites - Autoclave load).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Move In Time$q$, $q$Move In Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Hold Temperature$q$, $q$Hold Temperature (°C)$q$, $q$number$q$, $q$°C$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Start Temperature$q$, $q$Start Temperature (°C)$q$, $q$number$q$, $q$°C$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Finish Temperature$q$, $q$Finish Temperature (°C)$q$, $q$number$q$, $q$°C$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Ramp Up Rate$q$, $q$Ramp Up Rate (°C/min)$q$, $q$number$q$, $q$°C/min$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Ramp Down Rate$q$, $q$Ramp Down Rate (°C/min)$q$, $q$number$q$, $q$°C/min$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Dwell Time$q$, $q$Dwell Time (min)$q$, $q$number$q$, $q$min$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Parts per Load$q$, $q$Parts per Load$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 9, true),
    (v_id, $q$Load Cycle$q$, $q$Load Cycle (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Move In Time} + ({Hold Temperature} - {Start Temperature}) / {Ramp Up Rate} * 60 + {Dwell Time} * 60 + ({Hold Temperature} - {Finish Temperature}) / {Ramp Down Rate} * 60$q$, 10, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Load Cycle} / {Parts per Load} * {Cycle Time Factor}$q$, 11, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Composites - Autoclave cure$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Composites$q$ AND operation IN ($q$Autoclave Cure$q$);
END
$calc$;

