$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Composites - Ply complexity$q$, 19, 0),
    ($q$Composites - Hand ply placement$q$, 6, 0),
    ($q$Composites - Automated ply placement$q$, 10, 0),
    ($q$Composites - Ply cutting$q$, 16, 0),
    ($q$Composites - Core placement$q$, 8, 0),
    ($q$Composites - Ply material$q$, 11, 0),
    ($q$Composites - Core material$q$, 10, 0),
    ($q$Composites - Autoclave load$q$, 14, 0),
    ($q$Composites - Tool clean$q$, 7, 1),
    ($q$Composites - Mold preparation$q$, 12, 1),
    ($q$Composites - Ultrasonic cut$q$, 6, 1),
    ($q$Composites - Hand layup$q$, 24, 1),
    ($q$Composites - Automated layup$q$, 11, 2),
    ($q$Composites - Vacuum bag$q$, 15, 2),
    ($q$Composites - Autoclave cure$q$, 11, 1),
    ($q$Composites - Bench operation$q$, 6, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Composites$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1065: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
